-- +goose Up
-- +goose StatementBegin
-- Backfill ships.equipment + folded stat columns for existing player ships
-- (TASK-100.3.25), generated by cmd/starwind-tools/gen-ship-loadout-backfill.
-- Ships created before base-loadout spawning sit at equipment='[]' with only
-- their bare class stats. Each UPDATE fits the class's base module set
-- (ct_npc_ship_modules) and writes the equipment JSONB plus every stat the fold
-- touches. Only un-fitted, non-spacesuit, non-NPC ships are touched; shield and
-- energy are topped up to their new maxima. Do not edit by hand — rerun the
-- generator.

UPDATE ships SET
    equipment       = '[{"equipmentID":58,"type":"up_engine","level":1},{"equipmentID":38,"type":"up_shield","level":1},{"equipmentID":67,"type":"up_weapon_control","level":1},{"equipmentID":113,"type":"up_turret_control","level":3},{"equipmentID":1,"type":"up_launcher","level":5},{"equipmentID":10,"type":"up_pro","level":5}]'::jsonb,
    max_speed       = 11.34,
    acceleration    = 3.969,
    turn_rate       = 0.7853981633974483,
    max_shield      = 1138500,
    shield          = 1138500,
    shield_recharge = 9598,
    max_energy      = 100,
    energy          = 100,
    energy_recharge = 2,
    energy_delta    = -300,
    laser_damage    = 1743,
    radar_range     = 450,
    cargobay        = 68260
WHERE ship_class_id = 73 AND equipment = '[]'::jsonb AND is_spacesuit = false
  AND player_id NOT IN (SELECT id FROM players WHERE login = '__npc__');

