-- Undo: strip the backfilled equipment back to '[]'. The stat columns are
-- left as-is (a no-op reverse would need every ship's pre-backfill values,
-- which are not recorded); a re-run of Up recomputes them from the class base.
UPDATE ships SET equipment = '[]'::jsonb
WHERE is_spacesuit = false AND player_id NOT IN (SELECT id FROM players WHERE login = '__npc__');
